# Casa de la Cuadra (Pueblo Cantera), 9 x 7, interior (F2, contract 74; map id 181). column = i, row = j. A rider's tack room: saddle crates, barrels of feed, a net rack for the harnesses and a table.
# In-game trade (cindibex -> belubub): he wants a CINDIBEX and gives a BELUBUB whose nickname is the fixed ASCII text `tr_cua.nick` (the same in all four languages: the trade idiom of casa_mimo,
# contract 32.5). Flag 929 = the trade was done.
@map casa_cuadra
@size 9 7
@interior yes
@flag cua_done 929
@var cua_res 5
@var cua_want 6
@var cua_give 7
@bg 3
@fill floor_wood
@spawn door 4 5 N
@legend
  .  tile=floor_wood
  C  tile=none object=wall_corner
  w  tile=none object=wall_j
  y  tile=none object=wall_win_j
  |  tile=none object=wall_i
  q  tile=none object=wall_win_i
  H  object=crate_plain
  x  object=barrel
  N  object=net_rack
  T  object=table
  B  object=bookshelf interact=look text=casa.books
  R  npc=rider id=trader face=SW script=trader
  m  tile=mat
@grid
  Cwwywwyww
  |NNH.BHx.
  |...R...x
  |.....T..
  q.H......
  |......H.
  |...mm...
@warp m -> pueblo_cantera spawn=cuadra_door
@script trader npc
    npc_face_hero trader
    setv cua_want sp:cindibex
    setv cua_give sp:belubub
    name_var 0 cua_want
    name_var 1 cua_give
    jf cua_done after
    say tr_cua.hello
    ask trueque.ask
    jv 0 1 go
    say trueque.no
    end
  go:
    trade cindibex belubub tr_cua.nick cua_res
    jv cua_res 1 done
    jv cua_res 255 cancel
    say trueque.wrong
    end
  cancel:
    say trueque.no
    end
  done:
    setf cua_done
    say trueque.done
    end
  after:
    name_var 0 cua_give
    say trueque.after
@end
